import{_t as e,it as t,n,rt as r}from"./chunks/framework.BIpRff3v.js";var i=JSON.parse(`{"title":"Running one task through the pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"pipeline-running.md","filePath":"pipeline-running.md"}`),a={name:`pipeline-running.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="running-one-task-through-the-pipeline" tabindex="-1" dir="auto">Running one task through the pipeline <a class="header-anchor" href="#running-one-task-through-the-pipeline" aria-label="Permalink to “Running one task through the pipeline”">​</a></h1><h2 id="running-one-task-through-it" tabindex="-1" dir="auto">Running one task through it <a class="header-anchor" href="#running-one-task-through-it" aria-label="Permalink to “Running one task through it”">​</a></h2><ol><li dir="auto"><strong>New issue → Task.</strong> Fill in goal, acceptance criteria, size, area. <code>inbox.yml</code> labels it <code>stage:inbox</code> and adds it to the Project.</li><li dir="auto"><strong>Triage.</strong> If it is ready, add <code>stage:qualified</code>.</li><li dir="auto"><strong>Spec and plan</strong> (~2 min). One Claude run writes both and the workflow posts two comments (<code>&lt;!-- pipeline:spec --&gt;</code> and <code>&lt;!-- pipeline:plan --&gt;</code>). If every <a href="#spec-and-plan-auto-approval">auto-approval check</a> passes, the label moves straight to <code>stage:planned</code> and development starts. If one fails, the item goes to the router (an unclear issue or a plan that is too big goes to you).</li><li dir="auto"><strong>Develop</strong> (5 to 30 min). Claude implements on <code>issue-&lt;n&gt;-&lt;slug&gt;</code>, runs <code>pnpm verify</code>, and the workflow opens a <strong>draft PR</strong> linked to the issue.</li><li dir="auto"><strong>CI, preview.</strong> <code>ci</code> must pass. The preview comment links <code>https://&lt;owner&gt;.github.io/&lt;repo&gt;/pr-&lt;n&gt;/</code>.</li><li dir="auto"><strong>Copilot (optional).</strong> Only with <code>REQUIRE_COPILOT=true</code>: with CI green and no open threads, the pipeline requests Copilot; its comments are review threads for you to resolve (or <code>/disposition</code>). Off (the default), this step is skipped and the PR goes straight to step 7.</li><li dir="auto"><strong>You.</strong> On <code>stage:human-approval</code> the PR is marked ready and you are requested as code owner. Check the diff and the preview, approve, merge. The branch must be up to date with <code>main</code> (the ruleset enforces it).</li><li dir="auto"><strong>Done.</strong> The issue closes; the PR and the issue get <code>stage:done</code> and both cards move to Done. If you close the PR without merging instead, the issue gets a <code>pr_closed</code> note and comes back to you through the router.</li></ol><h3 id="when-it-stops-at-stage-needs-attention" tabindex="-1" dir="auto">When it stops at <code>stage:needs-attention</code> <a class="header-anchor" href="#when-it-stops-at-stage-needs-attention" aria-label="Permalink to “When it stops at stage:needs-attention”">​</a></h3><p dir="auto">Only the router sets this label. Read the router&#39;s latest <code>&lt;!-- pipeline:route --&gt;</code> note on the issue or PR: it says why it stopped, lists what was tried in each round (with run links) and every open question in one place. The outcome notes above it have the details. Then either finish the PR by hand (you are the reviewer anyway), or answer the questions / fix the cause and restart it. <strong>The only way to restart is the owner&#39;s <code>/restart</code> command.</strong> Removing the label or adding a stage label by hand does not restart anything (see below).</p><p dir="auto"><strong><code>/restart</code>.</strong> On the <strong>issue</strong>, the owner (<code>PIPELINE_OWNER_LOGIN</code>, a human account) posts one comment whose whole body is one line:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/restart &lt;qualified|planned&gt; &lt;reason, 10+ characters&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th dir="auto">Stage</th><th dir="auto">What it does</th><th dir="auto">Must be in <code>stage:needs-attention</code></th></tr></thead><tbody><tr><td dir="auto"><code>qualified</code></td><td dir="auto">spec + plan again: sets <code>stage:qualified</code> on the issue (also for an old item stuck in the deprecated <code>stage:spec</code>)</td><td dir="auto">the issue</td></tr><tr><td dir="auto"><code>planned</code></td><td dir="auto">develop again from the plan already on the issue: sets <code>stage:planned</code></td><td dir="auto">the issue</td></tr></tbody></table><p dir="auto"><code>restart.yml</code> checks the command in full: the commenter is the owner and a human, the comment was not edited (only new comments count), the issue is open, the issue is in <code>stage:needs-attention</code>, and the issue has fewer than <strong>3</strong> restarts so far. With an open PR on the issue, <code>qualified</code> and <code>planned</code> are refused (they would publish nothing): close the PR first. Any failed check gets one short bot reply and changes nothing. An accepted restart, in this order:</p><ol><li dir="auto">adds one to the issue&#39;s <strong>lifetime counter</strong> and appends the attempt <code>{id, at, by, reason, stage}</code> (<code>id</code> = <code>a&lt;count&gt;-&lt;comment id&gt;</code>) in the issue&#39;s <code>pipeline-state</code> comment. Only the bot writes it, labels never touch it, and it is never decremented or cleared. The state table shows <code>lifetime resets: n/3</code> and the latest attempt id;</li><li dir="auto">appends the route note <code>&lt;!-- pipeline:route restart attempt=&lt;id&gt; count=&lt;n&gt;/3 --&gt;</code> with the reason in a fenced block, on the issue;</li><li dir="auto">applies the stage label.</li></ol><p dir="auto"><strong>The limit.</strong> After 3 restarts an issue is parked for good: a 4th <code>/restart</code> gets the reply &quot;Lifetime restart limit (3) reached; close the issue or fix it in a local session.&quot; and changes nothing; the item stays in <code>stage:needs-attention</code>. (This is a two-week trial: the constant is <code>MAX_LIFETIME_RESETS</code> in <code>pipeline-lib.mjs</code>.)</p><p dir="auto"><strong>Label edits by hand do not restart anything.</strong> Loop budgets (the router&#39;s caps) are only ever refreshed by <code>/restart</code>. If a person removes <code>stage:needs-attention</code>, or adds a stage label while it is set, the item continues with the budget it already used and its next problem goes straight back to a human. <code>restart.yml</code> posts one note per parking that says so and points to <code>/restart</code>; it does not undo the label edit.</p><p dir="auto">Which stage for which stop:</p><ul><li dir="auto">spec + plan / develop (<code>plan</code>, <code>develop</code> problems): <code>/restart qualified</code> or <code>/restart planned</code>;</li><li dir="auto">approval or CI problems on the PR (<code>copilot_request_failed</code>, <code>ci_failed</code>): fix the cause (a pushed fix starts CI again), remove <code>stage:needs-attention</code> from the PR by hand (<strong>Pipeline · Approval</strong> leaves a parked PR alone) and run <strong>Pipeline · Approval</strong> manually with the PR number; or close the PR and <code>/restart planned</code>;</li><li dir="auto">closed PR (<code>pr_closed</code>, on the issue): reopen the PR, or <code>/restart qualified</code> / <code>/restart planned</code> (re-develop force-pushes its <code>issue-&lt;n&gt;-</code> branch), or close the issue;</li><li dir="auto">router: run <strong>Pipeline · Router</strong> manually with the item number to route the latest outcome note again (it goes to a human if that note was already routed).</li></ul><p dir="auto"><strong>How the budgets follow restarts.</strong> Router caps count the route notes after the latest <code>restart</code> note (<code>routeWindow</code>), or every route note when the item was never restarted. A route to a human neither opens a window nor counts as a round.</p><h2 id="spec-and-plan-auto-approval" tabindex="-1" dir="auto">Spec and plan (auto-approval) <a class="header-anchor" href="#spec-and-plan-auto-approval" aria-label="Permalink to “Spec and plan (auto-approval)”">​</a></h2><p dir="auto"><code>plan.yml</code> replaced the old two-stage flow (a spec stage, then a Claude plan). One read-only Claude run (<code>plan.md</code>, JSON schema) returns two separate artifacts, and a deterministic job posts each as its own bot comment under the same markers as before (<code>&lt;!-- pipeline:spec --&gt;</code>, <code>&lt;!-- pipeline:plan --&gt;</code>), so develop and the pipeline map read exactly what they used to:</p><ul><li dir="auto"><code>spec</code>: goal, acceptance criteria (each with a <code>testable</code> flag), RTL &amp; accessibility, test plan, out of scope, assumptions;</li><li dir="auto"><code>plan</code>: approach, changes (<code>project</code>, <code>file</code>, <code>change</code>, estimated <code>lines</code> per file), tests, risks, definition of done.</li></ul><p dir="auto">Nothing waits for a human. The item moves straight to <code>stage:planned</code> only if <strong>all</strong> of these hold (<code>evaluatePlanApproval</code> in <code>pipeline-lib.mjs</code>):</p><table tabindex="0"><thead><tr><th dir="auto">Check</th><th dir="auto">On failure</th></tr></thead><tbody><tr><td dir="auto">Both parts present, every required section non-empty, every change valid</td><td dir="auto"><code>invalid_output</code> → re-plan</td></tr><tr><td dir="auto">Every acceptance criterion non-empty and marked testable</td><td dir="auto"><code>spec_questions</code> → human</td></tr><tr><td dir="auto">No planned file is <strong>never approvable</strong> (see below)</td><td dir="auto"><code>protected_surface</code> → human (hard gate)</td></tr><tr><td dir="auto">The planner reports no need for secrets, CI or infrastructure</td><td dir="auto"><code>needs_secrets_ci_infra</code> → human (hard gate)</td></tr><tr><td dir="auto">At most <code>PLAN_MAX_FILES</code> (10) files and <code>PLAN_MAX_LINES</code> (400) lines</td><td dir="auto"><code>scope_split</code> → human</td></tr><tr><td dir="auto">The planner reports no instructions embedded in the issue</td><td dir="auto"><code>embedded_instructions</code> → human (hard gate)</td></tr></tbody></table><p dir="auto">Planned files that are protected but <strong>approvable</strong> (<code>package.json</code>, <code>pnpm-lock.yaml</code>, <code>pnpm-workspace.yaml</code>, <code>tools/workspace-plugin/</code>, <code>tools/pipeline-map/</code>) pass this check. The success outcome note and the plan comment then say that the owner must approve them before a PR opens (<a href="./pipeline.html#protected-change-approval">Protected-change approval</a>). Any never-approvable path (<code>.github/</code>, <code>CODEOWNERS</code>, <code>tools/security/</code>, <code>.claude/</code>, <code>.codex/</code>, <code>.pipeline/</code>, <code>.npmrc</code>, <code>.gitmodules</code>) is still <code>protected_surface</code>.</p><p dir="auto">The two size limits are constants at the top of the plan section of <code>pipeline-lib.mjs</code>, set for a two-week trial: tune them there. When several checks fail, the note carries every reason and the highest-priority code (gates first). The planner may also report a problem itself (<code>status: &quot;problem&quot;</code>); <code>agent_error</code> and <code>invalid_output</code> are only ever assigned by the workflow.</p><p dir="auto"><strong>Old items in <code>stage:spec</code>.</strong> Nothing sets <code>stage:spec</code> or starts a stage on it any more, so an item that was already there (its spec comment stays; the Project card stays in <strong>Spec</strong>) does not move by itself. Add <code>stage:qualified</code> to run the combined stage: it takes the old spec as an earlier version, overwrites both comments and continues to <code>stage:planned</code>. (A plan run that was already in flight when this changed still finishes the old way.) If the item already has both a spec and a plan comment you trust, <code>stage:planned</code> develops from them as they are. Old <code>spec</code>-stage outcome notes and <code>respec</code> route notes still parse: see <a href="./pipeline-router.html#router">Router</a>.</p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};